#!/usr/bin/env python3
"""Reconstruct committable manifests from live cluster objects.

Strips the server-managed fields that must never appear in a Fleet bundle:
cluster-assigned identity, status, and controller bookkeeping. What is left
should apply back cleanly as a no-op.

Usage: reconstruct.py <context> <namespace> <outdir> <kind/name> [kind/name ...]
"""
import pathlib
import subprocess
import sys

import yaml

# Top-level keys that are pure server state.
DROP_TOP = {"status"}

# metadata keys that the API server or a controller owns.
DROP_META = {
    "uid", "resourceVersion", "generation", "creationTimestamp",
    "selfLink", "managedFields", "ownerReferences",
}

# Annotations that are bookkeeping, not desired state.
DROP_ANNOT_EXACT = {
    "kubectl.kubernetes.io/last-applied-configuration",
    "deployment.kubernetes.io/revision",
}
# Annotation prefixes belonging to other controllers (Rancher UI, Helm, Fleet).
DROP_ANNOT_PREFIX = (
    "field.cattle.io/",
    "objectset.rio.cattle.io/",
    "meta.helm.sh/",
    "fleet.cattle.io/",
)
DROP_LABEL_PREFIX = (
    "objectset.rio.cattle.io/",
    "fleet.cattle.io/",
)
DROP_LABEL_EXACT = {"app.kubernetes.io/managed-by"}

# Per-kind spec fields that are defaulted or cluster-assigned.
DROP_SPEC = {
    "Service": {"clusterIP", "clusterIPs", "ipFamilies", "ipFamilyPolicy",
                "internalTrafficPolicy", "sessionAffinity"},
    "PersistentVolumeClaim": {"volumeName", "volumeMode"},
}


def clean(obj):
    kind = obj.get("kind", "")
    for k in DROP_TOP:
        obj.pop(k, None)

    meta = obj.get("metadata", {})
    for k in DROP_META:
        meta.pop(k, None)

    annot = meta.get("annotations") or {}
    for k in list(annot):
        if k in DROP_ANNOT_EXACT or k.startswith(DROP_ANNOT_PREFIX):
            annot.pop(k)
    if annot:
        meta["annotations"] = annot
    else:
        meta.pop("annotations", None)

    labels = meta.get("labels") or {}
    for k in list(labels):
        if k in DROP_LABEL_EXACT or k.startswith(DROP_LABEL_PREFIX):
            labels.pop(k)
    if labels:
        meta["labels"] = labels
    else:
        meta.pop("labels", None)

    spec = obj.get("spec") or {}
    for k in DROP_SPEC.get(kind, ()):
        spec.pop(k, None)

    # A defaulted-empty template metadata block is noise.
    tmpl = (spec.get("template") or {}).get("metadata")
    if isinstance(tmpl, dict):
        tmpl.pop("creationTimestamp", None)

    if kind == "PersistentVolumeClaim":
        # Bound PVCs carry the resolved class; keep it, it is desired state.
        spec.pop("dataSource", None)
        spec.pop("dataSourceRef", None)

    return obj


def main():
    context, namespace, outdir = sys.argv[1:4]
    targets = sys.argv[4:]
    outdir = pathlib.Path(outdir)
    outdir.mkdir(parents=True, exist_ok=True)

    for target in targets:
        kind, _, name = target.partition("/")
        raw = subprocess.run(
            ["kubectl", "--context", context, "-n", namespace,
             "get", kind, name, "-o", "yaml"],
            capture_output=True, text=True, check=True,
        ).stdout
        obj = clean(yaml.safe_load(raw))
        # Namespace comes from the bundle's defaultNamespace, not the manifest,
        # so a bundle stays portable and cannot fight Fleet over placement.
        obj["metadata"].pop("namespace", None)
        fname = f"{name}.{kind.lower()}.yaml"
        with open(outdir / fname, "w") as fh:
            yaml.safe_dump(obj, fh, sort_keys=False, width=100)
        print(f"  wrote {outdir / fname}")


if __name__ == "__main__":
    main()

